   244	    private void persistEffects(List<EffectIntent> intents, UUID claimId, Claim claim) {
   245	        Instant available = now().plus(dispatchDelay);
   246	        for (EffectIntent intent : intents) {
   247	            if (intent.id().equals("create_payment_request")) {
   248	                Object rawAmount = claim.facts().values().get("requestedAmount");
   249	                if (!(rawAmount instanceof BigDecimal amount)) throw invalid("Requested amount must be an exact decimal");
   250	                payments.create(claimId, UUID.randomUUID(), claim.currency(), amount);
   251	            }
   252	            outbox.enqueue(new OutboxRepository.Message(UUID.randomUUID(), claimId, intent.id(),
   253	                    writeJson(intent.payload()), 0, available));
   254	        }
   255	    }
