    31	        self.passwords = passwords
    32	        self.cookies = http.cookiejar.CookieJar()
    33	        self.opener = urllib.request.build_opener(urllib.request.HTTPCookieProcessor(self.cookies))
    34	
    35	    def call(self, username: str | None, method: str, path: str, *, body=None, key=None, csrf=None):
    36	        headers = {"Accept": "application/json"}
    37	        if body is not None:
    38	            headers["Content-Type"] = "application/json"
    39	        if key:
    40	            headers["Idempotency-Key"] = key
    41	        if csrf:
    42	            headers[csrf["csrfHeaderName"]] = csrf["csrfToken"]
    43	        if username:
    44	            auth = base64.b64encode(f"{username}:{self.passwords[username]}".encode()).decode()
    45	            headers["Authorization"] = f"Basic {auth}"
    46	        data = json.dumps(body, separators=(",", ":")).encode() if body is not None else None
    47	        request = urllib.request.Request(self.base + path, data=data, headers=headers, method=method)
    48	        try:
    49	            with self.opener.open(request, timeout=10) as response:
    50	                content = response.read()
    51	                return response.status, json.loads(content) if content else None, response.headers
    52	        except urllib.error.HTTPError as error:
    53	            content = error.read()
    54	            try:
    55	                parsed = json.loads(content) if content else None
    56	            except json.JSONDecodeError:
    57	                parsed = None
    58	            return error.code, parsed, error.headers
