     1	package com.papaya.claims.claim.domain;
     2	
     3	import java.math.BigDecimal;
     4	import java.util.ArrayList;
     5	import java.util.Collections;
     6	import java.util.LinkedHashMap;
     7	import java.util.List;
     8	import java.util.Map;
     9	import java.util.Objects;
    10	
    11	/** Immutable JSON object values. Nested maps and lists are defensively copied. */
    12	public record ClaimFacts(Map<String, Object> values) {
    13	    public ClaimFacts {
    14	        Objects.requireNonNull(values, "values");
    15	        values = immutableMap(values);
    16	    }
    17	
    18	    private static Map<String, Object> immutableMap(Map<?, ?> source) {
    19	        Map<String, Object> copy = new LinkedHashMap<>();
    20	        source.forEach((key, value) -> {
    21	            if (!(key instanceof String stringKey) || stringKey.isBlank()) {
    22	                throw new IllegalArgumentException("Fact keys must be nonblank strings");
    23	            }
    24	            copy.put(stringKey, immutableValue(value));
    25	        });
    26	        return Collections.unmodifiableMap(copy);
    27	    }
    28	
    29	    private static Object immutableValue(Object value) {
    30	        if (value == null || value instanceof String || value instanceof Boolean || value instanceof BigDecimal
    31	                || value instanceof Integer || value instanceof Long) return value;
    32	        if (value instanceof Number number) return new BigDecimal(number.toString());
    33	        if (value instanceof Map<?, ?> map) return immutableMap(map);
    34	        if (value instanceof List<?> list) {
    35	            List<Object> copy = new ArrayList<>(list.size());
    36	            list.forEach(item -> copy.add(immutableValue(item)));
    37	            return Collections.unmodifiableList(copy);
    38	        }
    39	        throw new IllegalArgumentException("Unsupported claim fact value type: " + value.getClass().getName());
    40	    }
    41	}

