315	    private Map<String, Object> mergeDocuments(Claim claim, Object existingRaw, Object patchRaw, Actor actor) {
316	        if (!(patchRaw instanceof Map<?, ?> patch) || patch.isEmpty()) throw invalid("documents must be a nonempty object");
317	        Map<String, Object> existing = existingRaw instanceof Map<?, ?> map ? mutableMap(map) : new LinkedHashMap<>();
318	        Map<String, Object> result = new LinkedHashMap<>(existing);
319	        for (var entry : patch.entrySet()) {
320	            if (!(entry.getKey() instanceof String id) || !DOCUMENT_ID.matcher(id).matches()) throw invalid("Document ID is invalid");
321	            if (!(entry.getValue() instanceof Map<?, ?> rawFields) || rawFields.isEmpty()) throw invalid("Document fields must be a nonempty object");
322	            boolean member = actor.hasRole("member");
323	            boolean clerk = actor.hasRole("document_clerk");
324	            if (member && !claim.memberId().equals(actor.id())) throw forbidden("Member does not own this claim");
325	            if (member && !claim.state().equals("PENDING_INFO")) throw forbidden("Members may add information only while a claim is pending information");
326	            if (clerk && !Set.of("SUBMITTED", "PENDING_INFO").contains(claim.state())) throw forbidden("Documents cannot be updated in this claim state");
327	            if (!member && !clerk) throw forbidden("Only the claim member or document clerk may update documents");
328	            Object oldRaw = existing.get(id);
329	            boolean isNew = oldRaw == null;
330	            if (member && isNew) throw forbidden("Members cannot add document roster entries");
331	            if (isNew && !clerk) throw forbidden("Only a document clerk may add document roster entries");
332	            Map<String, Object> fields = oldRaw instanceof Map<?, ?> map ? mutableMap(map) : new LinkedHashMap<>();
333	            for (var field : rawFields.entrySet()) {
334	                if (!(field.getKey() instanceof String name) || !(field.getValue() instanceof Boolean)) throw invalid("Document fields must be booleans");
335	                if (member && !name.equals("present")) throw forbidden("Members may only update document presence");
336	                if (clerk && !Set.of("required", "present", "valid").contains(name)) throw invalid("Unknown document field: " + name);
337	                if (name.equals("required") && !isNew && !claim.state().equals("SUBMITTED")) throw forbidden("Existing document required status is immutable after submission");
338	                fields.put(name, field.getValue());
339	            }
340	            if (!(fields.get("required") instanceof Boolean) || !(fields.get("present") instanceof Boolean)
341	                    || !(fields.get("valid") instanceof Boolean)) throw invalid("Document entry must contain required, present and valid boolean fields");
342	            result.put(id, Map.copyOf(fields));
343	        }
344	        return Map.copyOf(result);
345	    }
346	
347	    private static Map<String, Object> mutableMap(Map<?, ?> source) {
348	        Map<String, Object> result = new LinkedHashMap<>();
349	        source.forEach((k, v) -> { if (k instanceof String key) result.put(key, v); });
350	        return result;
351	    }
