353	    private ClaimAggregate lockedClaim(UUID id, Actor actor) {
354	        ClaimAggregate aggregate = claims.findForUpdate(id).orElseThrow(() -> notFound("Claim was not found"));
355	        requireVisible(aggregate.claim(), actor);
356	        return aggregate;
357	    }
358	
359	    private ClaimAggregate visibleClaim(UUID id, Actor actor, boolean lock) {
360	        requireActor(actor);
361	        ClaimAggregate aggregate = (lock ? claims.findForUpdate(id) : claims.find(id))
362	                .orElseThrow(() -> notFound("Claim was not found"));
363	        requireVisible(aggregate.claim(), actor);
364	        return aggregate;
365	    }
366	
367	    private static void requireVisible(Claim claim, Actor actor) {
368	        requireActor(actor);
369	        if (actor.hasRole("member") && !claim.memberId().equals(actor.id())) throw notFound("Claim was not found");
370	    }
371	
372	    private void lockAndCheckKey(Actor actor, String scope, String key) {
373	        idempotency.lock(actor.id(), scope, requireKey(key));
374	    }
375	
376	    private <T> Optional<T> replay(String actorId, String scope, String key, String fingerprint, Class<T> type) {
377	        IdempotencyRepository.Receipt receipt = idempotency.find(actorId, scope, key).orElse(null);
378	        if (receipt == null) return Optional.empty();
379	        if (!MessageDigest.isEqual(receipt.fingerprint().getBytes(StandardCharsets.US_ASCII), fingerprint.getBytes(StandardCharsets.US_ASCII)))
380	            throw new BusinessException("IDEMPOTENCY_CONFLICT", "Idempotency key was already used for a different request", 409);
381	        try { return Optional.of(json.readValue(receipt.resultJson(), type)); }
382	        catch (JsonProcessingException e) { throw new IllegalStateException("Stored idempotency result is invalid", e); }
383	    }
384	
385	    private void storeReceipt(String actor, String scope, String key, String fingerprint, Object result) {
386	        idempotency.insert(new IdempotencyRepository.Receipt(UUID.randomUUID(), actor, scope, key,
387	                fingerprint, writeJson(result)));
388	    }
389	
390	    private void writeSystemAudit(String action, String resource, String resourceId, Actor actor,
391	            String correlationId, String outcome, String errorType) {
392	        systemAudit.append(new SystemOperationAuditRecord(UUID.randomUUID(), action, resource, resourceId,
393	                actor.id(), safeCorrelation(correlationId), outcome, errorType, now()));
394	    }
395	
396	    private String fingerprint(Object request) {
397	        try {
398	            byte[] canonical = json.writeValueAsBytes(canonicalize(request));
399	            return HexFormatSupport.sha256(canonical);
400	        } catch (JsonProcessingException e) { throw new IllegalArgumentException("Could not fingerprint request", e); }
401	    }
402	
403	    private Object canonicalize(Object value) {
404	        if (value instanceof Map<?, ?> map) {
405	            Map<String, Object> sorted = new TreeMap<>();
406	            map.forEach((k, v) -> { if (k instanceof String key) sorted.put(key, canonicalize(v)); });
407	            return sorted;
408	        }
409	        if (value instanceof List<?> list) return list.stream().map(this::canonicalize).toList();
410	        return value;
411	    }
412	
413	    private String writeJson(Object value) {
414	        try { return json.writeValueAsString(value); }
415	        catch (JsonProcessingException e) { throw new IllegalArgumentException("Could not serialize persistence result", e); }
416	    }
417	
418	    private Instant now() { return clock.instant().truncatedTo(ChronoUnit.MICROS); }
419	    private static Claim replace(Claim old, String state, ClaimFacts facts, long version, Instant updated) {
420	        return new Claim(old.id(), old.memberId(), state, old.policyLimit(), old.currency(), version, facts, old.createdAt(), updated);
421	    }
422	
423	    private String matchingRole(Actor actor, String transitionId) {
424	        if (actor.system()) return "system";
425	        return definition.transitions().stream().filter(t -> t.id().equals(transitionId)).findFirst()
426	                .map(t -> t.roles().stream().filter(actor::hasRole).sorted().findFirst().orElse("unknown"))
427	                .orElse("unknown");
428	    }
429	
430	    private static String requireKey(String key) {
431	        if (key == null || !IDEMPOTENCY_KEY.matcher(key).matches()) throw invalid("Idempotency-Key must contain 1 to 128 safe characters");
432	        return key;
433	    }
434	    private static String safeCorrelation(String value) {
435	        return value != null && CORRELATION_ID.matcher(value).matches() ? value : UUID.randomUUID().toString();
436	    }
437	    private static void checkVersion(Claim claim, long expected) { if (claim.version() != expected) throw versionConflict(); }
438	    private static BusinessException versionConflict() { return new BusinessException("VERSION_CONFLICT", "Claim version is stale", 409); }
439	    private static BusinessException notFound(String m) { return new BusinessException("NOT_FOUND", m, 404); }
440	    private static BusinessException forbidden(String m) { return new BusinessException("FORBIDDEN", m, 403); }
441	    private static BusinessException invalid(String m) { return new BusinessException("INVALID_REQUEST", m, 400); }
442	    private static void requireActor(Actor actor) { if (actor == null) throw forbidden("Authentication is required"); }
443	    private static void requireHuman(Actor actor) {
444	        requireActor(actor);
445	        if (actor.system()) throw forbidden("System identity cannot perform human operations");
446	        if (actor.roles().stream().noneMatch(HUMAN_ROLES::contains)) throw forbidden("Authenticated human role is required");
447	    }
448	    private static void requireRole(Actor actor, String role) { if (!actor.hasRole(role)) throw forbidden("Required role is missing"); }
449	    private static void validateRequestedAmount(Object amount) {
450	        if (amount == null) return;
451	        if (!(amount instanceof BigDecimal value) || value.signum() < 0 || value.scale() > 2 || value.precision() - value.scale() > 16)
452	            throw invalid("requestedAmount must be a nonnegative exact decimal fitting NUMERIC(18,2)");
453	    }
454	
455	    private static final class HexFormatSupport {
456	        private static String sha256(byte[] content) {
457	            try {
458	                byte[] digest = MessageDigest.getInstance("SHA-256").digest(content);
459	                StringBuilder result = new StringBuilder(64);
460	                for (byte b : digest) result.append(Character.forDigit((b >>> 4) & 0xf, 16)).append(Character.forDigit(b & 0xf, 16));
461	                return result.toString();
462	            } catch (NoSuchAlgorithmException e) { throw new IllegalStateException("SHA-256 is unavailable", e); }
463	        }
464	    }
465	}
