     1	package com.papaya.claims.workflow;
     2	
     3	import java.util.List;
     4	
     5	public final class WorkflowEngine {
     6	    private final WorkflowDefinition definition;
     7	    private final GuardEvaluator guards;
     8	    private final EffectRegistry effects;
     9	
    10	    public WorkflowEngine(WorkflowDefinition definition, GuardEvaluator guards) {
    11	        this(definition, guards, new EffectRegistry());
    12	    }
    13	
    14	    public WorkflowEngine(WorkflowDefinition definition, GuardEvaluator guards, EffectRegistry effects) {
    15	        this.definition = definition;
    16	        this.guards = guards;
    17	        this.effects = effects;
    18	        if (!effects.strategyIds().containsAll(definition.effects().keySet()))
    19	            throw new IllegalArgumentException("Workflow definition contains an unregistered effect strategy");
    20	    }
    21	    public List<WorkflowOption> available(WorkflowEvaluationContext c) {
    22	        return definition.transitions().stream().filter(t -> t.from().equals(c.claim().state())).map(t -> {
    23	            List<String> failures = failures(t, c);
    24	            return new WorkflowOption(t.id(), t.from(), t.to(), t.roles(), failures.isEmpty(), failures, t.effects());
    25	        }).toList();
    26	    }
    27	    public WorkflowDecision evaluate(WorkflowEvaluationContext c) {
    28	        List<WorkflowOption> opts=available(c); WorkflowDefinition.Transition t=definition.transitions().stream().filter(x->x.from().equals(c.claim().state())&&x.to().equals(c.command().targetState())).findFirst().orElse(null);
    29	        if(t==null) {
    30	            String choices = opts.stream().map(option -> option.transitionId() + " -> " + option.to())
    31	                    .collect(java.util.stream.Collectors.joining(", "));
    32	            String message = "No configured transition from " + c.claim().state() + " to "
    33	                    + c.command().targetState() + ". Available transitions: " + (choices.isEmpty() ? "none" : choices);
    34	            return new WorkflowDecision(false, null, c.claim().state(), c.command().targetState(),
    35	                    "INVALID_EDGE", message, List.of(), opts);
    36	        }
    37	        if(!t.roles().stream().anyMatch(c.actor()::hasRole)) return WorkflowDecision.denied("ROLE_FORBIDDEN","Actor is not authorized for this transition",opts);
    38	        for(String g:t.guards()) if(!guards.passes(g,c)) return WorkflowDecision.denied(g.toUpperCase(java.util.Locale.ROOT),definition.guardMessages().get(g),opts);
    39	        WorkflowDefinition.CyclePolicy cycle = definition.cyclePolicy();
    40	        if(t.id().equals(cycle.transitionId()) && c.evidence().counterValue(cycle.counter())>=cycle.maximum())
    41	            return WorkflowDecision.denied("CYCLE_LIMIT",cycle.errorMessage(),opts);
    42	        List<EffectIntent> plannedEffects = t.effects().stream().map(id -> effects.resolve(id, c)).toList();
    43	        return new WorkflowDecision(true,t.id(),t.from(),t.to(),null,null,plannedEffects,opts);
    44	    }
    45	    private List<String> failures(WorkflowDefinition.Transition t, WorkflowEvaluationContext c) {
    46	        List<String> failures = new java.util.ArrayList<>();
    47	        if (t.roles().stream().noneMatch(c.actor()::hasRole)) failures.add("ROLE_FORBIDDEN");
    48	        for (String guard : t.guards()) if (!guards.passes(guard, c)) failures.add(guard);
    49	        WorkflowDefinition.CyclePolicy cycle = definition.cyclePolicy();
    50	        if (t.id().equals(cycle.transitionId()) && c.evidence().counterValue(cycle.counter()) >= cycle.maximum()) failures.add("CYCLE_LIMIT");
    51	        return List.copyOf(failures);
    52	    }
    53	}

