 47	    @Test
 48	    void idempotencyTransactionLockSerializesSameKeyAndExposesCommittedReceipt() throws Exception {
 49	        String actor = "actor-concurrent";
 50	        String scope = "claim.create";
 51	        String key = "same-key-" + UUID.randomUUID();
 52	        CountDownLatch firstLocked = new CountDownLatch(1);
 53	        CountDownLatch releaseFirst = new CountDownLatch(1);
 54	        CountDownLatch secondAttempting = new CountDownLatch(1);
 55	        CountDownLatch secondLocked = new CountDownLatch(1);
 56	        ExecutorService pool = Executors.newFixedThreadPool(2);
 57	        var transactionManager = new DataSourceTransactionManager(runtimeDataSource());
 58	        var first = pool.submit(() -> new TransactionTemplate(transactionManager).execute(status -> {
 59	            var repository = new MyBatisIdempotencyRepository(receipts(), JSON);
 60	            repository.lock(actor, scope, key);
 61	            firstLocked.countDown();
 62	            await(releaseFirst);
 63	            repository.insert(new Receipt(UUID.randomUUID(), actor, scope, key, "b".repeat(64), "{}"));
 64	            return null;
 65	        }));
 66	        try {
 67	            assertThat(firstLocked.await(5, TimeUnit.SECONDS)).isTrue();
 68	            var second = pool.submit(() -> new TransactionTemplate(transactionManager).execute(status -> {
 69	                var repository = new MyBatisIdempotencyRepository(receipts(), JSON);
 70	                secondAttempting.countDown();
 71	                repository.lock(actor, scope, key);
 72	                secondLocked.countDown();
 73	                return repository.find(actor, scope, key).orElseThrow();
 74	            }));
 75	            assertThat(secondAttempting.await(5, TimeUnit.SECONDS)).isTrue();
 76	            assertThat(secondLocked.await(250, TimeUnit.MILLISECONDS)).isFalse();
 77	            releaseFirst.countDown();
 78	            assertThat(first.get(10, TimeUnit.SECONDS)).isNull();
 79	            assertThat(second.get(10, TimeUnit.SECONDS).idempotencyKey()).isEqualTo(key);
 80	            assertThat(secondLocked.getCount()).isZero();
 81	        } finally {
 82	            releaseFirst.countDown();
 83	            pool.shutdownNow();
 84	            assertThat(pool.awaitTermination(5, TimeUnit.SECONDS)).isTrue();
 85	        }
 86	    }
