 88	    private static boolean compete(UUID id, String state, Instant now, CountDownLatch ready, CountDownLatch start) throws Exception {
 89	        var tx = new TransactionTemplate(new DataSourceTransactionManager(runtimeDataSource()));
 90	        ready.countDown();
 91	        if (!start.await(5, TimeUnit.SECONDS)) throw new AssertionError("CAS start gate timed out");
 92	        return Boolean.TRUE.equals(tx.execute(status -> {
 93	            var repository = new MyBatisClaimRepository(claims(), JSON);
 94	            var before = repository.find(id).orElseThrow().claim();
 95	            var next = new ClaimAggregate(new Claim(id, before.memberId(), state, before.policyLimit(),
 96	                    before.currency(), before.version() + 1, before.facts(), before.createdAt(), now), ClaimWorkflowData.empty());
 97	            return repository.compareAndSet(next, before.version());
 98	        }));
 99	    }
