102	        try {
103	            if (!latch.await(5, TimeUnit.SECONDS)) throw new AssertionError("transaction release timed out");
104	        } catch (InterruptedException e) {
105	            Thread.currentThread().interrupt();
106	            throw new AssertionError("transaction interrupted", e);
107	        }
108	    }
