     9	import org.springframework.stereotype.Repository;
    10	import org.springframework.beans.factory.annotation.Value;
    11	
    12	@Repository
    13	public class MyBatisOutboxRepository implements OutboxRepository {
    14	    private final EffectsMapper mapper; private final long leaseMillis;
    15	    public MyBatisOutboxRepository(EffectsMapper mapper,
    16	            @Value("${claims.outbox.lease-duration-ms:30000}") long leaseMillis) {
    17	        if (leaseMillis < 1) throw new IllegalArgumentException("Outbox lease duration must be positive");
    18	        this.mapper=mapper; this.leaseMillis=leaseMillis;
    19	    }
    20	    @Override public void enqueue(Message m) {
    21	        OutboxRow r=new OutboxRow(); r.id=m.id(); r.claimId=m.claimId(); r.effect=m.effect(); r.payloadJson=m.payload();
    22	        r.attempts=m.attempts(); r.availableAt=m.availableAt(); r.traceparent=m.traceparent(); mapper.enqueue(r);
    23	    }
    24	    @Override public List<Message> claimDue(Instant now,int limit) {
    25	        if(limit<1) throw new IllegalArgumentException("limit must be positive");
    26	        return mapper.claimDue(now,limit,leaseMillis).stream().map(r -> new Message(r.id,r.claimId,r.effect,r.payloadJson,r.attempts,r.availableAt,r.traceparent)).toList();
    27	    }
    28	    @Override public boolean markDelivered(UUID id,Instant at) { return mapper.delivered(id,at)==1; }
    29	    @Override public boolean markFailed(UUID id,String safeError,Instant retryAt) { return mapper.failed(id,safeError,retryAt)==1; }
