     1	package com.papaya.claims.claim.effects;
     2	
     3	import com.papaya.claims.claim.domain.OutboxRepository;
     4	import com.papaya.claims.common.web.Traceparent;
     5	import io.opentelemetry.api.OpenTelemetry;
     6	import io.opentelemetry.api.trace.Span;
     7	import io.opentelemetry.api.trace.StatusCode;
     8	import io.opentelemetry.context.Context;
     9	import io.opentelemetry.context.Scope;
    10	import io.micrometer.core.instrument.MeterRegistry;
    11	import java.time.Clock;
    12	import java.time.Duration;
    13	import java.util.List;
    14	import org.slf4j.Logger;
    15	import org.slf4j.LoggerFactory;
    16	import org.springframework.beans.factory.annotation.Value;
    17	import org.springframework.beans.factory.annotation.Autowired;
    18	import org.springframework.scheduling.annotation.Scheduled;
    19	import org.springframework.stereotype.Component;
    20	import org.springframework.transaction.annotation.Transactional;
    21	
    22	@Component
    23	public class OutboxDispatcher {
    24	    private static final Logger log = LoggerFactory.getLogger(OutboxDispatcher.class);
    25	    private final OutboxRepository outbox;
    26	    private final EffectDelivery delivery;
    27	    private final Clock clock;
    28	    private final Duration retryDelay;
    29	    private final int batchSize;
    30	    private final MeterRegistry metrics;
    31	    private final OpenTelemetry openTelemetry;
    32	
    33	    @Autowired
    34	    public OutboxDispatcher(OutboxRepository outbox, EffectDelivery delivery, Clock clock, MeterRegistry metrics,
    35	            OpenTelemetry openTelemetry,
    36	            @Value("${claims.outbox.retry-delay-ms:5000}") long retryDelayMs,
    37	            @Value("${claims.outbox.batch-size:32}") int batchSize) {
    38	        if (retryDelayMs < 1 || batchSize < 1) throw new IllegalArgumentException("Outbox retry delay and batch size must be positive");
    39	        this.outbox = outbox; this.delivery = delivery; this.clock = clock;
    40	        this.retryDelay = Duration.ofMillis(retryDelayMs); this.batchSize = batchSize; this.metrics = metrics;
    41	        this.openTelemetry = openTelemetry;
    42	    }
    43	
    44	    public OutboxDispatcher(OutboxRepository outbox, EffectDelivery delivery, Clock clock, MeterRegistry metrics,
    45	            long retryDelayMs, int batchSize) {
    46	        this(outbox, delivery, clock, metrics, OpenTelemetry.noop(), retryDelayMs, batchSize);
    47	    }
    48	
    49	    private void deliverWithTrace(OutboxRepository.Message message) {
    50	        Context parent = Traceparent.parent(message.traceparent()).orElse(null);
    51	        if (parent == null) {
    52	            delivery.deliver(message);
    53	            return;
    54	        }
    55	        Span span = openTelemetry.getTracer("claims-workflow-outbox")
    56	                .spanBuilder("claims.outbox.delivery")
    57	                .setParent(parent)
    58	                .setAttribute("claims.outbox.effect", message.effect())
    59	                .startSpan();
    60	        try (Scope ignored = span.makeCurrent()) {
    61	            delivery.deliver(message);
    62	        } catch (RuntimeException failure) {
    63	            span.recordException(failure);
    64	            span.setStatus(StatusCode.ERROR);
    65	            throw failure;
    66	        } finally {
    67	            span.end();
    68	        }
    69	    }
    70	
    71	    @Scheduled(fixedDelayString = "${claims.outbox.poll-interval-ms:1000}")
    72	    @Transactional
    73	    public void dispatchDue() {
    74	        List<OutboxRepository.Message> batch = outbox.claimDue(clock.instant(), batchSize);
    75	        for (OutboxRepository.Message message : batch) {
    76	            try {
    77	                deliverWithTrace(message);
    78	                if (outbox.markDelivered(message.id(), clock.instant())) {
    79	                    metrics.counter("claims.outbox.delivered", "effect", message.effect()).increment();
    80	                }
    81	            } catch (RuntimeException failure) {
    82	                outbox.markFailed(message.id(), failure.getClass().getSimpleName(), clock.instant().plus(retryDelay));
    83	                metrics.counter("claims.outbox.failed", "effect", message.effect()).increment();
    84	                log.warn("mock_effect_delivery_failed eventId={} effect={} exceptionType={}",
    85	                        message.id(), message.effect(), failure.getClass().getSimpleName());
    86	            }
    87	        }
    88	    }
    89	}

