   216	        checkVersion(current.claim(), command.expectedVersion());
   217	        ClaimFacts merged = command.suppliedFacts().values().isEmpty()
   218	                ? current.claim().facts() : mergeFacts(current.claim(), command.suppliedFacts(), actor);
   219	        Claim candidate = replace(current.claim(), current.claim().state(), merged,
   220	                current.claim().version(), current.claim().updatedAt());
