     1	#!/usr/bin/env bash
     2	set -euo pipefail
     3	umask 077
     4	profile=${1:?usage: scripts/performance/run-profile.sh PROFILE [--no-setup]}
     5	case "$profile" in baseline|normal|peak|stress|spike|soak|concurrent-claims) ;; *) echo "Unknown profile: $profile" >&2; exit 2;; esac
     6	root=$(cd "$(dirname "$0")/../.." && pwd)
     7	cd "$root"
     8	: "${JAVA_HOME:=/home/tringuyen/.local/java/jdk-21}"
     9	: "${JMETER_HOME:=/home/tringuyen/.local/jmeter}"
    10	export JAVA_HOME
    11	export PATH="$JAVA_HOME/bin:$PATH"
    12	mkdir -p reports/performance
    13	out="reports/performance/${profile}-$(date -u +%Y%m%dT%H%M%SZ)"
    14	mkdir -p "$out"
    15	printf '{"jmeter":"Apache JMeter 5.6.3","java":"Java 21","profile":"%s","host":"127.0.0.1","port":8080,"threads":%s,"ramp_seconds":%s,"duration_seconds":%s,"approved_targets":{"p95_ms":500,"p99_ms":1000,"error_rate_max":0.01}}\n' "$profile" "${JMETER_THREADS:-$(awk -F= '$1=="threads"{print $2} ' performance/jmeter/profiles/${profile}.properties)}" "${JMETER_RAMP:-$(awk -F= '$1=="ramp"{print $2} ' performance/jmeter/profiles/${profile}.properties)}" "${JMETER_DURATION:-$(awk -F= '$1=="duration"{print $2} ' performance/jmeter/profiles/${profile}.properties)}" > "$out/run.json"
    16	python3 scripts/performance/monitor.py "$out/system-metrics.jsonl" & monitor_pid=$!
    17	trap 'kill "$monitor_pid" 2>/dev/null || true; wait "$monitor_pid" 2>/dev/null || true; rm -f "$out/credentials.properties"' EXIT
    18	# Avoid retaining credentials or putting them on the process command line.
    19	CLAIMS_ENV_FILE=${CLAIMS_ENV_FILE:-.env} python3 scripts/performance/read-secret.py > "$out/credentials.properties"
    20	chmod 600 "$out/credentials.properties"
    21	"$JMETER_HOME/bin/jmeter" -n -t "performance/jmeter/profiles/${profile}.jmx" \
    22	  -q "performance/jmeter/profiles/${profile}.properties" \
    23	  -q "$out/credentials.properties" ${JMETER_THREADS:+-Jthreads="$JMETER_THREADS"} ${JMETER_RAMP:+-Jramp="$JMETER_RAMP"} ${JMETER_DURATION:+-Jduration="$JMETER_DURATION"} -Jjmeterengine.nongui.port=0 -Jjmeterengine.nongui.maxport=0 \
    24	  -l "$out/results.jtl" -j "$out/jmeter.log" -e -o "$out/html-report"
    25	python3 scripts/performance/summarize-jtl.py "$out/results.jtl" > "$out/summary.json"
    26	kill "$monitor_pid" 2>/dev/null || true
    27	wait "$monitor_pid" 2>/dev/null || true
    28	trap - EXIT
    29	rm -f "$out/credentials.properties"
    30	echo "Results: $out"
