     1	package com.papaya.claims.common.web;
     2	
     3	import jakarta.servlet.FilterChain;
     4	import jakarta.servlet.ServletException;
     5	import jakarta.servlet.http.HttpServletRequest;
     6	import jakarta.servlet.http.HttpServletResponse;
     7	import java.io.IOException;
     8	import java.util.UUID;
     9	import java.util.regex.Pattern;
    10	import org.slf4j.Logger;
    11	import org.slf4j.LoggerFactory;
    12	import org.slf4j.MDC;
    13	import org.springframework.core.Ordered;
    14	import org.springframework.core.annotation.Order;
    15	import org.springframework.stereotype.Component;
    16	import org.springframework.web.filter.OncePerRequestFilter;
    17	
    18	@Component
    19	@Order(Ordered.HIGHEST_PRECEDENCE)
    20	public class CorrelationIdFilter extends OncePerRequestFilter {
    21	    public static final String HEADER = "X-Correlation-ID";
    22	    public static final String ATTRIBUTE = CorrelationIdFilter.class.getName() + ".id";
    23	    private static final Pattern SAFE = Pattern.compile("[A-Za-z0-9._:-]{1,128}");
    24	    private static final Logger log = LoggerFactory.getLogger(CorrelationIdFilter.class);
    25	    public CorrelationIdFilter() { }
    26	
    27	    @Override
    28	    protected void doFilterInternal(HttpServletRequest request, HttpServletResponse response, FilterChain chain)
    29	            throws ServletException, IOException {
    30	        String supplied = request.getHeader(HEADER);
    31	        String correlationId = supplied != null && SAFE.matcher(supplied).matches() ? supplied : UUID.randomUUID().toString();
    32	        request.setAttribute(ATTRIBUTE, correlationId);
    33	        response.setHeader(HEADER, correlationId);
    34	        MDC.put("correlationId", correlationId);
    35	        long started = System.nanoTime();
    36	        try {
    37	            chain.doFilter(request, response);
    38	        } finally {
    39	            long durationMs = (System.nanoTime() - started) / 1_000_000;
    40	            Traceparent.Ids trace = Traceparent.ids(request.getHeader("traceparent")).orElse(null);
    41	            log.info("http_request method={} path={} status={} durationMs={} correlationId={} traceId={} parentSpanId={}",
    42	                    request.getMethod(), request.getRequestURI(), response.getStatus(), durationMs, correlationId,
    43	                    trace == null ? null : trace.traceId(), trace == null ? null : trace.parentSpanId());
    44	            MDC.remove("correlationId");
    45	        }
    46	    }
    47	
    48	    public static String currentId(HttpServletRequest request) {
    49	        Object value = request.getAttribute(ATTRIBUTE);
    50	        return value instanceof String id ? id : UUID.randomUUID().toString();
    51	    }
    52	}

