     1	package com.papaya.claims.common.web;
     2	
     3	import io.opentelemetry.api.trace.Span;
     4	import io.opentelemetry.api.trace.SpanContext;
     5	import io.opentelemetry.api.trace.TraceFlags;
     6	import io.opentelemetry.api.trace.TraceState;
     7	import io.opentelemetry.context.Context;
     8	import java.util.Optional;
     9	import java.util.regex.Matcher;
    10	import java.util.regex.Pattern;
    11	
    12	/** Converts active W3C trace context to/from the durable local-outbox carrier. */
    13	public final class Traceparent {
    14	    private static final Pattern FORMAT = Pattern.compile("00-([0-9a-f]{32})-([0-9a-f]{16})-([0-9a-f]{2})");
    15	    private Traceparent() { }
    16	
    17	    public static String current() {
    18	        SpanContext context = Span.current().getSpanContext();
    19	        if (!context.isValid()) return null;
    20	        return "00-" + context.getTraceId() + "-" + context.getSpanId() + "-" + context.getTraceFlags().asHex();
    21	    }
    22	
    23	    public static Optional<Ids> ids(String value) {
    24	        if (value == null) return Optional.empty();
    25	        Matcher matcher = FORMAT.matcher(value);
    26	        if (!matcher.matches()) return Optional.empty();
    27	        SpanContext parsed = SpanContext.createFromRemoteParent(matcher.group(1), matcher.group(2),
    28	                TraceFlags.fromHex(matcher.group(3), 0), TraceState.getDefault());
    29	        return parsed.isValid() ? Optional.of(new Ids(parsed.getTraceId(), parsed.getSpanId())) : Optional.empty();
    30	    }
    31	
    32	    public static Optional<Context> parent(String value) {
    33	        return ids(value).map(ids -> {
    34	            SpanContext parsed = SpanContext.createFromRemoteParent(ids.traceId(), ids.parentSpanId(),
    35	                    TraceFlags.fromHex(value.substring(value.length() - 2), 0), TraceState.getDefault());
    36	            return Context.root().with(Span.wrap(parsed));
    37	        });
    38	    }
    39	
    40	    public record Ids(String traceId, String parentSpanId) { }
    41	}

