     5	import io.opentelemetry.api.trace.Span;
     6	import io.opentelemetry.api.trace.SpanContext;
     7	import io.opentelemetry.api.trace.TraceFlags;
     8	import io.opentelemetry.api.trace.TraceState;
     9	import io.opentelemetry.context.Context;
    10	import io.opentelemetry.context.Scope;
    11	import org.junit.jupiter.api.Test;
    12	
    13	class TraceparentTest {
    14	    private static final String TRACE = "0123456789abcdef0123456789abcdef";
    15	    private static final String PARENT = "0123456789abcdef";
    16	
    17	    @Test
    18	    void capturesAndRestoresW3cTraceContext() {
    19	        SpanContext remote = SpanContext.createFromRemoteParent(TRACE, PARENT, TraceFlags.getSampled(), TraceState.getDefault());
    20	        try (Scope ignored = Context.root().with(Span.wrap(remote)).makeCurrent()) {
    21	            String value = Traceparent.current();
    22	            assertThat(value).isEqualTo("00-" + TRACE + "-" + PARENT + "-01");
    23	            Context restored = Traceparent.parent(value).orElseThrow();
    24	            assertThat(Span.fromContext(restored).getSpanContext().getTraceId()).isEqualTo(TRACE);
    25	            assertThat(Span.fromContext(restored).getSpanContext().getSpanId()).isEqualTo(PARENT);
    26	            assertThat(Traceparent.ids(value).orElseThrow())
    27	                    .isEqualTo(new Traceparent.Ids(TRACE, PARENT));
    28	        }
    29	    }
    30	
    31	    @Test
    32	    void ignoresAbsentMalformedUnsupportedAndInvalidTraceparents() {
    33	        assertThat(Traceparent.current()).isNull();
    34	        assertThat(Traceparent.parent(null)).isEmpty();
    35	        assertThat(Traceparent.parent("not-a-traceparent")).isEmpty();
    36	        assertThat(Traceparent.parent("01-" + TRACE + "-" + PARENT + "-01")).isEmpty();
    37	        assertThat(Traceparent.parent("00-00000000000000000000000000000000-" + PARENT + "-01")).isEmpty();
    38	        assertThat(Traceparent.ids("00-00000000000000000000000000000000-" + PARENT + "-01")).isEmpty();
    39	    }
    40	}

