package com.papaya.claims.common.web;

import jakarta.servlet.FilterChain;
import jakarta.servlet.ServletException;
import jakarta.servlet.http.HttpServletRequest;
import jakarta.servlet.http.HttpServletResponse;
import java.io.IOException;
import java.util.UUID;
import java.util.regex.Pattern;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;
import org.slf4j.MDC;
import org.springframework.core.Ordered;
import org.springframework.core.annotation.Order;
import org.springframework.stereotype.Component;
import org.springframework.web.filter.OncePerRequestFilter;

@Component
@Order(Ordered.HIGHEST_PRECEDENCE)
public class CorrelationIdFilter extends OncePerRequestFilter {
    public static final String HEADER = "X-Correlation-ID";
    public static final String ATTRIBUTE = CorrelationIdFilter.class.getName() + ".id";
    private static final Pattern SAFE = Pattern.compile("[A-Za-z0-9._:-]{1,128}");
    private static final Logger log = LoggerFactory.getLogger(CorrelationIdFilter.class);
    public CorrelationIdFilter() { }

    @Override
    protected void doFilterInternal(HttpServletRequest request, HttpServletResponse response, FilterChain chain)
            throws ServletException, IOException {
        String supplied = request.getHeader(HEADER);
        String correlationId = supplied != null && SAFE.matcher(supplied).matches() ? supplied : UUID.randomUUID().toString();
        request.setAttribute(ATTRIBUTE, correlationId);
        response.setHeader(HEADER, correlationId);
        MDC.put("correlationId", correlationId);
        long started = System.nanoTime();
        try {
            chain.doFilter(request, response);
        } finally {
            long durationMs = (System.nanoTime() - started) / 1_000_000;
            Traceparent.Ids trace = Traceparent.ids(request.getHeader("traceparent")).orElse(null);
            log.info("http_request method={} path={} status={} durationMs={} correlationId={} traceId={} parentSpanId={}",
                    request.getMethod(), request.getRequestURI(), response.getStatus(), durationMs, correlationId,
                    trace == null ? null : trace.traceId(), trace == null ? null : trace.parentSpanId());
            MDC.remove("correlationId");
        }
    }

    public static String currentId(HttpServletRequest request) {
        Object value = request.getAttribute(ATTRIBUTE);
        return value instanceof String id ? id : UUID.randomUUID().toString();
    }
}
package com.papaya.claims.common.web;

import io.opentelemetry.api.trace.Span;
import io.opentelemetry.api.trace.SpanContext;
import io.opentelemetry.api.trace.TraceFlags;
import io.opentelemetry.api.trace.TraceState;
import io.opentelemetry.context.Context;
import java.util.Optional;
import java.util.regex.Matcher;
import java.util.regex.Pattern;

/** Converts active W3C trace context to/from the durable local-outbox carrier. */
public final class Traceparent {
    private static final Pattern FORMAT = Pattern.compile("00-([0-9a-f]{32})-([0-9a-f]{16})-([0-9a-f]{2})");
    private Traceparent() { }

    public static String current() {
        SpanContext context = Span.current().getSpanContext();
        if (!context.isValid()) return null;
        return "00-" + context.getTraceId() + "-" + context.getSpanId() + "-" + context.getTraceFlags().asHex();
    }

    public static Optional<Ids> ids(String value) {
        if (value == null) return Optional.empty();
        Matcher matcher = FORMAT.matcher(value);
        if (!matcher.matches()) return Optional.empty();
        SpanContext parsed = SpanContext.createFromRemoteParent(matcher.group(1), matcher.group(2),
                TraceFlags.fromHex(matcher.group(3), 0), TraceState.getDefault());
        return parsed.isValid() ? Optional.of(new Ids(parsed.getTraceId(), parsed.getSpanId())) : Optional.empty();
    }

    public static Optional<Context> parent(String value) {
        return ids(value).map(ids -> {
            SpanContext parsed = SpanContext.createFromRemoteParent(ids.traceId(), ids.parentSpanId(),
                    TraceFlags.fromHex(value.substring(value.length() - 2), 0), TraceState.getDefault());
            return Context.root().with(Span.wrap(parsed));
        });
    }

    public record Ids(String traceId, String parentSpanId) { }
}
package com.papaya.claims.common.web;

import static org.assertj.core.api.Assertions.assertThat;
import static org.assertj.core.api.Assertions.assertThatThrownBy;

import org.junit.jupiter.api.Test;
import org.slf4j.MDC;
import org.springframework.mock.web.MockHttpServletRequest;
import org.springframework.mock.web.MockHttpServletResponse;

class CorrelationIdFilterTest {
    @Test
    void preservesOnlyBoundedSafeIdsAndReturnsTheEffectiveCorrelationId() throws Exception {
        var filter = new CorrelationIdFilter();
        var request = new MockHttpServletRequest("GET", "/api/v1/claims");
        request.addHeader("X-Correlation-ID", "client:trace-17");
        var response = new MockHttpServletResponse();
        filter.doFilter(request, response, (req, res) -> assertThat(MDC.get("correlationId")).isEqualTo("client:trace-17"));
        assertThat(response.getHeader("X-Correlation-ID")).isEqualTo("client:trace-17");
        assertThat(MDC.get("correlationId")).isNull();
    }

    @Test
    void replacesMalformedOrOversizedIdsWithGeneratedUuid() throws Exception {
        var filter = new CorrelationIdFilter();
        var request = new MockHttpServletRequest("GET", "/api/v1/claims");
        request.addHeader("X-Correlation-ID", "bad value");
        var response = new MockHttpServletResponse();
        filter.doFilter(request, response, (req, res) -> { });
        String effective = response.getHeader("X-Correlation-ID");
        assertThat(effective).matches("[0-9a-f-]{36}");
    }

    @Test
    void removesMdcAndStopsObservationWhenDownstreamFails() throws Exception {
        var filter = new CorrelationIdFilter();
        var request = new MockHttpServletRequest("POST", "/api/v1/claims");
        request.addHeader("X-Correlation-ID", "valid-17");
        var response = new MockHttpServletResponse();
        assertThatThrownBy(() -> filter.doFilter(request, response, (req, res) -> {
            throw new java.io.IOException("downstream failed");
        })).isInstanceOf(java.io.IOException.class).hasMessage("downstream failed");
